<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LensPic Payment Receipt</title><style>body{margin:0;background:#f5f7fb;color:#172033;font-family:Arial,sans-serif}.receipt{box-sizing:border-box;width:min(760px,calc(100% - 32px));margin:32px auto;background:#fff;border:1px solid #dce3ef;border-radius:16px;padding:32px}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:1px solid #e5e7eb;padding-bottom:20px}.brand{font-size:24px;font-weight:800;color:#4f46e5}.muted{color:#64748b}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:24px 0}.label{font-size:12px;text-transform:uppercase;color:#64748b}.value{margin-top:5px;font-weight:600;overflow-wrap:anywhere}.total{font-size:20px;color:#166534}.actions{text-align:center;margin-top:28px}.actions button{border:0;border-radius:10px;background:#4f46e5;color:#fff;padding:12px 20px;font-weight:700}@media(max-width:560px){.receipt{padding:20px}.head,.grid{display:block}.grid>div{margin-bottom:16px}}@media print{body{background:#fff}.receipt{border:0;margin:0;width:100%}.actions{display:none}}</style></head><body><main class="receipt"><header class="head"><div><div class="brand">{{ $merchant }}</div><div class="muted">LensPic payment receipt</div></div><div><strong>Receipt</strong><div class="muted">{{ $payment['reference'] }}</div></div></header><section class="grid"><div><div class="label">Customer</div><div class="value">{{ $order->user->name }}<br>{{ $order->user->email }}</div></div><div><div class="label">Plan</div><div class="value">{{ $payment['plan'] }} · {{ $payment['billing_cycle'] }}</div></div><div><div class="label">Base amount</div><div class="value">{{ $payment['base_amount'] }}</div></div><div><div class="label">GST ({{ $payment['gst_rate'] }}%)</div><div class="value">{{ $payment['gst_amount'] }}</div></div><div><div class="label">Total paid</div><div class="value total">{{ $payment['total_amount'] }}</div></div><div><div class="label">Payment status</div><div class="value">Paid</div></div><div><div class="label">Payment reference</div><div class="value">{{ $payment['payment_id'] }}<br>{{ $payment['reference'] }}</div></div><div><div class="label">Payment date</div><div class="value">{{ $order->paid_at?->timezone(config('app.timezone'))->format('d M Y, h:i A') }}</div></div></section><p class="muted">This is a payment receipt, not a tax invoice.</p><div class="actions"><button onclick="window.print()">Print / Save PDF</button></div></main></body></html>
